import React from 'react';
import {
  Box,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import type { Document } from '../services/documentService';
import {
  formatBillAmount,
  getBillTransactionPreview,
  getBillTransactionTotal,
} from '../utils/extractedDataVerification';

export interface ExtractedBillTransactionsPreviewProps {
  document: Document;
  compact?: boolean;
}

const ExtractedBillTransactionsPreview: React.FC<ExtractedBillTransactionsPreviewProps> = ({
  document,
  compact = false,
}) => {
  const transactions = getBillTransactionPreview(document);
  const totalAmount = getBillTransactionTotal(transactions);

  if (transactions.length === 0) {
    return (
      <Box sx={{ mt: compact ? 1.5 : 2 }}>
        <Typography variant={compact ? 'subtitle2' : 'subtitle1'} sx={{ fontWeight: 600, mb: 0.5 }}>
          Bill transactions
        </Typography>
        <Typography variant="body2" color="text.secondary">
          No transaction amounts were extracted from this bill yet.
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ mt: compact ? 1.5 : 2 }}>
      <Typography variant={compact ? 'subtitle2' : 'subtitle1'} sx={{ fontWeight: 600, mb: 0.5 }}>
        Bill transactions
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
        Review the amounts extracted from your bill. These are read-only and will be used for carbon calculations
        after you verify the bill details above.
      </Typography>

      <TableContainer
        sx={{
          border: '1px solid',
          borderColor: 'divider',
          borderRadius: 1,
          bgcolor: 'background.paper',
        }}
      >
        <Table size="small" aria-label="Extracted bill transactions">
          <TableHead>
            <TableRow>
              <TableCell>Description</TableCell>
              <TableCell align="right" sx={{ width: 140 }}>
                Amount
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {transactions.map((transaction) => (
              <TableRow key={transaction.id}>
                <TableCell>
                  <Typography variant="body2">{transaction.description}</Typography>
                </TableCell>
                <TableCell align="right">
                  <Typography variant="body2" sx={{ fontWeight: 500 }}>
                    {formatBillAmount(transaction.amount)}
                  </Typography>
                </TableCell>
              </TableRow>
            ))}
            <TableRow>
              <TableCell>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                  Total
                </Typography>
              </TableCell>
              <TableCell align="right">
                <Typography variant="body2" sx={{ fontWeight: 700 }}>
                  {formatBillAmount(totalAmount)}
                </Typography>
              </TableCell>
            </TableRow>
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default ExtractedBillTransactionsPreview;
