import React, { useState } from 'react';
import {
  Alert,
  Button,
  Card,
  CardContent,
  Stack,
  TextField,
  Typography
} from '@mui/material';
import PaymentIcon from '@mui/icons-material/Payment';
import UploadFileIcon from '@mui/icons-material/UploadFile';
import api from '../../services/api';

export default function UpiDocumentPortalPanel() {
  const [sessionId, setSessionId] = useState('');
  const [upiDeepLink, setUpiDeepLink] = useState('');
  const [upiReference, setUpiReference] = useState('');
  const [status, setStatus] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [message, setMessage] = useState('');

  const createSession = async () => {
    const res = await api.createUpiDocumentSession();
    if (res.success && res.data) {
      setSessionId(res.data.sessionId);
      setUpiDeepLink(res.data.upiDeepLink || '');
      setStatus(res.data.status);
      setMessage('Pay via UPI, then enter your UTR to unlock upload.');
    }
  };

  const confirmPayment = async () => {
    if (!sessionId) return;
    const res = await api.confirmUpiDocumentPayment(sessionId, upiReference);
    if (res.success) {
      setStatus(res.data?.status || 'ready_for_upload');
      setMessage('Payment confirmed — upload your bill below.');
    }
  };

  const upload = async () => {
    if (!sessionId || !file) return;
    const res = await api.uploadUpiDocument(sessionId, file);
    if (res.success) setMessage(`Uploaded ${file.name} via UPI document portal.`);
  };

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack spacing={2}>
          <Typography variant="h6">UPI Document Portal</Typography>
          <Typography variant="body2" color="text.secondary">
            Pay a small UPI fee to unlock a bill-upload session — separate from subscription billing. Ideal for MSMEs who pay via PhonePe, GPay, or Paytm and attach electricity, diesel, or material invoices in the same flow.
          </Typography>
          <Button variant="contained" startIcon={<PaymentIcon />} onClick={createSession}>
            Start UPI upload session
          </Button>
          {upiDeepLink && (
            <TextField fullWidth size="small" label="UPI deep link" value={upiDeepLink} InputProps={{ readOnly: true }} />
          )}
          {sessionId && (
            <>
              <TextField
                fullWidth
                size="small"
                label="UPI payment reference (UTR)"
                value={upiReference}
                onChange={(e) => setUpiReference(e.target.value)}
              />
              <Button variant="outlined" onClick={confirmPayment}>
                Confirm payment
              </Button>
              <Button variant="outlined" component="label" startIcon={<UploadFileIcon />}>
                Select bill
                <input hidden type="file" accept=".pdf,image/*" onChange={(e) => setFile(e.target.files?.[0] || null)} />
              </Button>
              <Button variant="contained" onClick={upload} disabled={!file || status !== 'ready_for_upload'}>
                Upload via UPI portal
              </Button>
            </>
          )}
          {message && <Alert severity="success">{message}</Alert>}
        </Stack>
      </CardContent>
    </Card>
  );
}
